+  path_point->set_dkappa(
+      Interpolation::lerp(pp0.dkappa(), t0, pp1.dkappa(), t1, t));
+  path_point->set_ddkappa(
+      Interpolation::lerp(pp0.ddkappa(), t0, pp1.ddkappa(), t1, t));
+  path_point->set_s(Interpolation::lerp(pp0.s(), t0, pp1.s(), t1, t));
+
+  return tp;
+}
