-  std::vector<SLPoint> sl_points;
-  common::math::Vec2d location(state.pose().position().x(),
-                           state.pose().position().y());
-  std::uint32_t next_route_index = current_route_index_;
-  for (std::uint32_t i = current_route_index_;
