+  fg_objects->clear();
+  bg_objects->clear();
+
+  for (size_t i = 0; i < objects->size(); i++) {
+    if ((*objects)[i]->object_ptr->is_background) {
+      (*objects)[i]->object_ptr->track_id = ObjectTrack::GetNextTrackId();
