+void InsertFrontTrajectoryPoints(const Iter& start, const Iter& end,
+                                 ADCTrajectory* trajectory_pb) {
+  if (start == end) {
+    AINFO << "No points to prepend to ADCTrajectory.";
+    return;
+  }
