+
+  // beyond end of lane
+  EXPECT_DOUBLE_EQ(-0.2656845063517943, map_->HeadingOnLane(lane_info, 1000.0));
+}
+
+TEST_F(PredictionMapTest, get_lane_width) {
+  std::shared_ptr<const LaneInfo> lane_info = map_->LaneById("l20");
