-void Camera::load_projection_matrix(bool reset) const
-{
-    // WARNING: makeCurrent must be called by every calling method
-    glMatrixMode(GL_PROJECTION);
-
-    if (reset)
-    glLoadIdentity();
-
-    compute_projection_matrix();
-
-    glMultMatrixd(_projection_matrix);
