-
-    double halfWidth = focus_distance() * tan(horizontalfield_of_view() / 2.0);
-    double shift     = halfWidth * io_distance() / physicalscreen_width(); // * current window width / full screen width
-
-    compute_model_view_matrix();
-    if (leftBuffer){
-    _model_view_matrix[12] -= shift;}
-    else{
-    _model_view_matrix[12] += shift;}
-    glLoadMatrixd(_model_view_matrix);
