-void Camera::fit_screen_region(const Eigen::Vector2i& topLeft, Eigen::Vector2i& bottomRight)
-{
-    const Eigen::Vector3d vd = view_direction();
-    const double distToPlane = distance_to_scene_center();
-    const Eigen::Vector2i center = (topLeft + bottomRight) / 2.0;
-
-    Eigen::Vector3d orig;
-    Eigen::Vector3d dir;
-    convert_click_to_line( center, orig, dir );
-    Eigen::Vector3d newCenter = orig + distToPlane / dir.dot(vd) * dir;
-
-    convert_click_to_line( Eigen::Vector2i(topLeft(0), center(1)), orig, dir );
-    const Eigen::Vector3d pointX = orig + distToPlane / dir.dot(vd) * dir;
-
-    convert_click_to_line( Eigen::Vector2i(center(0), topLeft(1)), orig, dir );
-    const Eigen::Vector3d pointY = orig + distToPlane / dir.dot(vd) * dir;
-
-    double distance = 0.0f;
-    switch (type())
-    {
-    case Camera::PERSPECTIVE :
-    {
-    const double distX = (pointX-newCenter).norm() / sin(horizontalfield_of_view() / 2.0);
-    const double distY = (pointY-newCenter).norm() / sin(field_of_view() / 2.0);
-    distance = std::max(distX, distY);
-    break;
-    }
-    case Camera::ORTHOGRAPHIC :
-    {
-    const double dist = (newCenter-revolve_around_point()).dot(vd);
-    //#CONNECTION# get_ortho_width_height
-    const double distX = (pointX-newCenter).norm() / _ortho_coef / ((aspect_ratio() < 1.0) ? 1.0 : aspect_ratio());
-    const double distY = (pointY-newCenter).norm() / _ortho_coef / ((aspect_ratio() < 1.0) ? 1.0 / aspect_ratio() : 1.0);
-    distance = dist + std::max(distX, distY);
-    break;
-    }
-    }
-
-    Eigen::Vector3d newPos(newCenter - distance * vd);
-    frame()->set_position(newPos);
-}
