-Eigen::Vector3d Camera::projectedcoordinates_of(const Eigen::Vector3d& src, const Frame* frame) const
-{
-    GLdouble x = 0.0;
-    GLdouble y = 0.0;
-    GLdouble z = 0.0;
-    static GLint viewport[4];
-    get_viewport(viewport);
-
-    if (frame)
-    {
-    const Eigen::Vector3d tmp = frame->inverse_coordinates_of(src);    
-    gluProject(tmp(0),tmp(1),tmp(2), _model_view_matrix, _projection_matrix, viewport,    &x,&y,&z);
-    }
-    else
-    gluProject(src(0),src(1),src(2), _model_view_matrix, _projection_matrix, viewport,    &x,&y,&z);
-
-    return Eigen::Vector3d(x,y,z);
-}
