-Eigen::Vector3d Camera::unprojectedcoordinates_of(const Eigen::Vector3d& src, const Frame* frame) const
-{
-    GLdouble x = 0.0;
-    GLdouble y = 0.0;
-    GLdouble z = 0.0;
-    static GLint viewport[4];
-    get_viewport(viewport);
-    gluUnProject(src(0),src(1),src(2), _model_view_matrix,    _projection_matrix,    viewport,    &x,&y,&z);
-    if (frame){
-    return frame->coordinates_of(Eigen::Vector3d(x,y,z));}
-    else{
-    return Eigen::Vector3d(x,y,z);}
-}
-
-void Camera::get_projectedcoordinates_of(const double src[3], double res[3], const Frame* frame) const
