-void Camera::convert_click_to_line(const Eigen::Vector2i& pixel, Eigen::Vector3d& orig, Eigen::Vector3d& dir) const
-{
-    switch (type())
-    {
-    case Camera::PERSPECTIVE:
-    orig = position();
-    dir = Eigen::Vector3d( ((2.0 * pixel(0) / screen_width()) - 1.0) * tan(field_of_view() / 2.0) * aspect_ratio(),
-     ((2.0 * (screen_height() - pixel(1)) / screen_height()) - 1.0) * tan(field_of_view() / 2.0),
-     -1.0 );
-    dir = worldcoordinates_of(dir) - orig;
-    dir.normalize();
-    break;
-
-    case Camera::ORTHOGRAPHIC:
-    {
-    GLdouble w = 0.0;
-    GLdouble h = 0.0; 
-    get_ortho_width_height(w,h);
-    orig = Eigen::Vector3d((2.0 * pixel(0) / screen_width() - 1.0) * w, -(2.0 * pixel(1) / screen_height() - 1.0) * h, 0.0);
-    orig = worldcoordinates_of(orig);
-    dir = view_direction();
-    break;
-    }
-    }
-}
