-
-    Eigen::Vector3d rotAxis = get_quaternion_axis(rotation);
-    Eigen::Vector3d resRotAxis = inverse_transform_of(rotAxis);
-    resRotAxis.normalize();
-    double rotAngle = get_quaternion_angle(rotation);
