-void Frame::align_with_frame(const Frame* const frame, bool move, double threshold) {
-  Eigen::Vector3d directions[2][3];
-  for (int d = 0; d < 3; ++d) {
-      Eigen::Vector3d dir((d==0)? 1.0 : 0.0, (d==1)? 1.0 : 0.0, (d==2)? 1.0 : 0.0);
