-	        directions[0][d] = dir;}
-      directions[1][d] = inverse_transform_of(dir);
-  }
-
-  double maxProj = 0.0f;
-  double proj = 0.0;
-  unsigned short index[2];
-  index[0] = index[1] = 0;
-  for (int i=0; i<3; ++i){
-    for (int j=0; j<3; ++j){
-		if ((proj=fabs(directions[0][i].dot(directions[1][j]))) >= maxProj) {
-    	  index[0] = i;
-    	  index[1] = j;
-    	  maxProj  = proj;
-          }
-     }
-  }
-
-  Frame old;
-  old=*this;
-
-  double coef = directions[0][index[0]].dot(directions[1][index[1]]);
-  if (fabs(coef) >= threshold) {
-		  const Eigen::Vector3d axis =  directions[0][index[0]].cross(directions[1][index[1]]);
-      double angle = asin(axis.norm());
-      if (coef >= 0.0)
-	       angle = -angle;
-      // set_orientation(Eigen::Quaterniond(axis, angle) * orientation());
-      //axis.normalize();
-      Eigen::AngleAxisd angleAxis(angle, axis);
-      rotate(rotation().inverse() * Eigen::Quaterniond(angleAxis) * orientation());
-
-      // Try to align an other axis direction
-      unsigned short d = (index[1]+1) % 3;
-      Eigen::Vector3d dir((d==0)? 1.0 : 0.0, (d==1)? 1.0 : 0.0, (d==2)? 1.0 : 0.0);
-      dir = inverse_transform_of(dir);
-
-      double max = 0.0f;
-      for (int i=0; i<3; ++i) {
-    		double proj = fabs(directions[0][i].dot(dir));
-    	  if (proj > max) {
-    	      index[0] = i;
-    	      max = proj;
-    	  }
-    	}
-
-      if (max >= threshold) {
-    		const Eigen::Vector3d axis = directions[0][index[0]].cross(dir);
-    	  double angle = asin(axis.norm());
-    	  if (directions[0][index[0]].dot(dir) >= 0.0)
