+#include "frame.h"
+
+#include <math.h>
+#include <iostream>
+
+namespace apollo {
+namespace perception {
+
+//using namespace std;    
+
+const double frame_pi = 3.141592653;    
+
+void get_quaternion_axis_angle(const Eigen::Quaterniond& quat, 
+    Eigen::Vector3d& axis, 
+    float& angle) 
+{
+    angle = 2.0*acos(quat.w());
+    axis = Eigen::Vector3d(quat.x(), quat.y(), quat.z());                   
+    const double sinus = axis.norm();
+    if (sinus > 1E-8)
+        axis /= sinus;      
+
+    if (angle > frame_pi) {
+        angle = 2.0*frame_pi - angle;
+        axis = -axis;
+    }
+}
+
+Eigen::Vector3d get_quaternion_axis(const Eigen::Quaterniond& quat) {
+    Eigen::Vector3d res(quat.x(), quat.y(), quat.z());
+    const double sinus = res.norm();
+    if (sinus > 1E-8)
+        res /= sinus;
+    Eigen::Vector3d invRes = -res;  //just for avoiding the gcc bug on "? :"
+    return (acos(quat.w()) <= frame_pi / 2.0) ? res : invRes;
+}
+
+double get_quaternion_angle(const Eigen::Quaterniond& quat) {
+    const double angle = 2.0 * acos(quat.w());
+    return (angle <= frame_pi) ? angle : 2.0 * frame_pi - angle;
+}
+
+
+Frame::Frame() :  
+_reference_frame(NULL),
+_t(0, 0, 0),
+_q(Eigen::Quaterniond(1, 0, 0, 0)){
+}
+
+Frame::Frame(const Eigen::Vector3d& position, const Eigen::Quaterniond& orientation)
+  : _t(position), _q(orientation), _reference_frame(NULL) {
+}
+
+
+Frame& Frame::operator=(const Frame& frame) {
+  // Automatic compiler generated version would not emit the modified() signals as is done in
+  // set_translation_and_rotation.
+  set_translation_and_rotation(frame.translation(), frame.rotation());
+  set_reference_frame(frame.reference_frame());
+  return *this;
+}
+
+Frame::Frame(const Frame& frame) {
+    (*this) = frame;
+}
+
+const double* Frame::matrix() const {
+    static double m[4][4];
+    get_matrix(m);
+    return (const double*)(m);
+}
+
+void Frame::get_matrix(double m[4][4]) const {
+    Eigen::Matrix3d rotMat = _q.toRotationMatrix();
+    m[0][0] = rotMat(0,0);
+    m[0][1] = rotMat(1,0);
+    m[0][2] = rotMat(2,0);
+    m[1][0] = rotMat(0,1);
+    m[1][1] = rotMat(1,1);
+    m[1][2] = rotMat(2,1);
+    m[2][0] = rotMat(0,2);
+    m[2][1] = rotMat(1,2);
+    m[2][2] = rotMat(2,2);
+    m[3][0] = _t(0);
+    m[3][1] = _t(1);
+    m[3][2] = _t(2);
+    m[0][3] = 0;
+    m[1][3] = 0;
+    m[2][3] = 0;
+    m[3][3] = 1.0l;
+}
+
+void Frame::get_matrix(double m[16]) const {
+    Eigen::Matrix3d rotMat = _q.toRotationMatrix();
+    m[0] = rotMat(0,0);
+    m[1] = rotMat(1,0);
+    m[2] = rotMat(2,0);
+    m[3] = 0;
+    m[4] = rotMat(0,1);
+    m[5] = rotMat(1,1);
+    m[6] = rotMat(2,1);
+    m[7] = 0;
+    m[8]  = rotMat(0,2);
+    m[9]  = rotMat(1,2);
+    m[10] = rotMat(2,2);
+    m[11] = 0;
+    m[12] = _t(0);
+    m[13] = _t(1);
+    m[14] = _t(2);
+    m[15] = 1.0l;
+}
+
+Frame Frame::inverse() const {
+    Frame fr(-(_q.inverse()._transformVector(_t)), _q.inverse());
+    fr.set_reference_frame(reference_frame());
+    return fr;
+}
+
+const double* Frame::world_matrix() const {
+    // This test is done for efficiency reasons (creates lots of temp objects otherwise).
+    if (reference_frame())
+    {
+        static Frame fr;
+        fr.set_translation(position());
+        fr.set_rotation(orientation());
+        return fr.matrix();
+    }
+    else
+        return matrix();
+}
+
+void Frame::get_world_matrix(double m[4][4]) const {
+    const double* mat = world_matrix();
+    for (int i=0; i<4; ++i)
+        {for (int j=0; j<4; ++j)
+           {m[i][j] = mat[i*4+j];
+           }
+        }
+}
+
+void Frame::get_world_matrix(double m[16]) const {
+    const double* mat = world_matrix();
+    for (int i=0; i<16; ++i)
+        {m[i] = mat[i];}
+}
+
+void Frame::set_from_matrix(const double m[4][4]) {
+    if (fabs(m[3][3]) < 1E-8) {
+        std::cout<<"Frame::set_from_matrix: Null homogeneous coefficient"<<std::endl;
+        return;
+    }
+
+    Eigen::Matrix3d rot;
+    for (int i=0; i<3; ++i) {
+        _t[i] = m[3][i] / m[3][3];
+        for (int j=0; j<3; ++j)
+  	        {rot(i,j) = m[j][i] / m[3][3];}
+    }
+    _q = Eigen::Quaterniond(rot);
+}
+
+void Frame::set_from_matrix(const double m[16]) {
+    double mat[4][4];
+    for (int i=0; i<4; ++i){
+        for (int j=0; j<4; ++j)
+            {mat[i][j] = m[i*4+j];}
+    }
+    set_from_matrix(mat);
+}
+
+void Frame::set_translation(double x, double y, double z) {
+    set_translation(Eigen::Vector3d(x, y, z));
+}
+
+void Frame::get_translation(double& x, double& y, double& z) const {
+    const Eigen::Vector3d t = translation();
+    x = t(0);
+    y = t(1);
+    z = t(2);
+}
+
+void Frame::set_rotation(double q0, double q1, double q2, double q3) {
+    set_rotation(Eigen::Quaterniond(q3, q0, q1, q2));
+}
+
+void Frame::get_rotation(double& q0, double& q1, double& q2, double& q3) const {
+    const Eigen::Quaterniond q = rotation();
+    q0 = q.x();
+    q1 = q.y();
+    q2 = q.z();
+    q3 = q.w();
+}
+
+void Frame::translate(const Eigen::Vector3d& t) {
+    Eigen::Vector3d tbis = t;
+    translate(tbis);
+}
+
+void Frame::translate(Eigen::Vector3d& t) {
+    _t += t;
+}
+
+void Frame::translate(double x, double y, double z) {
+    Eigen::Vector3d t(x,y,z);
+    translate(t);
+}
+
+void Frame::translate(double& x, double& y, double& z) {
+    Eigen::Vector3d t(x,y,z);
+    translate(t);
+    x = t(0);
+    y = t(1);
+    z = t(2);
+}
+
+void Frame::rotate(const Eigen::Quaterniond& q) {
+    Eigen::Quaterniond qbis = q;
+    rotate(qbis);
+}
+
+void Frame::rotate(Eigen::Quaterniond& q) {
+    _q *= q;
+    _q.normalize(); // Prevents numerical drift
+}
+
+void Frame::rotate(double& q0, double& q1, double& q2, double& q3) {
+    Eigen::Quaterniond q(q3,q0,q1,q2);
+    rotate(q);
+    q0 = q.x();
+    q1 = q.y();
+    q2 = q.z();
+    q3 = q.w();
+}
+
+void Frame::rotate(double q0, double q1, double q2, double q3) {
+    Eigen::Quaterniond q(q3,q0,q1,q2);
+    rotate(q);
+}
+
+void Frame::rotate_around_point(Eigen::Quaterniond& rotation, const Eigen::Vector3d& point) {
+    _q *= rotation;
+    _q.normalize(); // Prevents numerical drift
+
+    Eigen::Vector3d rotAxis = get_quaternion_axis(rotation);
+    Eigen::Vector3d resRotAxis = inverse_transform_of(rotAxis);
+    resRotAxis.normalize();
+    double rotAngle = get_quaternion_angle(rotation);
+    Eigen::AngleAxisd angleAxis(rotAngle, resRotAxis);
+
+    Eigen::Vector3d trans = point + Eigen::Quaterniond(angleAxis)._transformVector(position()-point) - _t;
+
+    _t += trans;
+}
+
+void Frame::rotate_around_point(const Eigen::Quaterniond& rotation, const Eigen::Vector3d& point) {
+    Eigen::Quaterniond rot = rotation;
+    rotate_around_point(rot, point);
+}
