+void Frame::set_position(const Eigen::Vector3d& position) {
+    if (reference_frame())
+        set_translation(reference_frame()->coordinates_of(position));
+    else
+        set_translation(position);
+}
+
+void Frame::set_position(double x, double y, double z) {
+  set_position(Eigen::Vector3d(x, y, z));
+}
+
+void Frame::set_position_and_orientation(const Eigen::Vector3d& position, const Eigen::Quaterniond& orientation) {
+    if (reference_frame()) {
+        _t = reference_frame()->coordinates_of(position);
+        _q = reference_frame()->orientation().inverse() * orientation;
+    }
+    else {
+        _t = position;
+        _q = orientation;
+    }
+}
+
+void Frame::set_translation_and_rotation(const Eigen::Vector3d& translation, const Eigen::Quaterniond& rotation) {
+  _t = translation;
+  _q = rotation;
+}
