+void Frame::get_orientation(double& q0, double& q1, double& q2, double& q3) const {
+  Eigen::Quaterniond o = orientation();
+  q0 = o.x();
+  q1 = o.y();
+  q2 = o.z();
+  q3 = o.w();
+}
+
+Eigen::Quaterniond Frame::orientation() const {
+  Eigen::Quaterniond res = rotation();
+  const Frame* fr = reference_frame();
+  while (fr != NULL) {
+      res = fr->rotation() * res;
+      fr  = fr->reference_frame();
+    }
+  return res;
+}
+
+void Frame::set_reference_frame(const Frame* const refFrame) {
+  if (setting_asreference_frame_will_create_a_loop(refFrame))
+     std::cerr <<"Frame::set_reference_frame would create a loop in Frame hierarchy";
+  else {
+      _reference_frame = refFrame;
+  }
+}
+
+bool Frame::setting_asreference_frame_will_create_a_loop(const Frame* const frame) {
+  const Frame* f = frame;
+  while (f != NULL) {
+      if (f == this)
+	        return true;
+      f = f->reference_frame();
+  }
+  return false;
+}
+
+Eigen::Vector3d Frame::coordinates_of(const Eigen::Vector3d& src) const {
+  if (reference_frame())
+     return local_coordinates_of(reference_frame()->coordinates_of(src));
+  else
+     return local_coordinates_of(src);
+}
+
+Eigen::Vector3d Frame::inverse_coordinates_of(const Eigen::Vector3d& src) const {
+  const Frame* fr = this;
+  Eigen::Vector3d res = src;
+  while (fr != NULL) {
+      res = fr->local_inverse_coordinates_of(res);
+      fr  = fr->reference_frame();
+  }
+  return res;
+}
+
+Eigen::Vector3d Frame::local_coordinates_of(const Eigen::Vector3d& src) const {
+  return rotation().inverse()._transformVector(src - translation());
+}
+
+Eigen::Vector3d Frame::local_inverse_coordinates_of(const Eigen::Vector3d& src) const {
+  return rotation()._transformVector(src) + translation();
+}
+
+Eigen::Vector3d Frame::coordinates_of_from(const Eigen::Vector3d& src, const Frame* const from) const {
+  if (this == from)
+    return src;
+  else
+    if (reference_frame())
+      return local_coordinates_of(reference_frame()->coordinates_of_from(src, from));
+    else
+      return local_coordinates_of(from->inverse_coordinates_of(src));
+}
+
+Eigen::Vector3d Frame::coordinates_of_in(const Eigen::Vector3d& src, const Frame* const in) const {
+  const Frame* fr = this;
+  Eigen::Vector3d res = src;
+  while ((fr != NULL) && (fr != in)) {
+      res = fr->local_inverse_coordinates_of(res);
+      fr  = fr->reference_frame();
+    }
+
+  if (fr != in)
+    // in was not found in the branch of this, res is now expressed in the world
+    // coordinate system. Simply convert to in coordinate system.
+    res = in->coordinates_of(res);
+
+  return res;
+}
+
+void Frame::get_coordinates_of(const double src[3], double res[3]) const {
+  const Eigen::Vector3d r = coordinates_of(Eigen::Vector3d(src[0],src[1],src[2]));
+  for (int i = 0; i < 3; ++i){
+    res[i] = r[i];}
+}
+
+void Frame::get_inverse_coordinates_of(const double src[3], double res[3]) const {
+  const Eigen::Vector3d r = inverse_coordinates_of(Eigen::Vector3d(src[0],src[1],src[2]));
+  for (int i = 0; i < 3; ++i){
