+}
+
+void Frame::get_local_inverse_coordinates_of(const double src[3], double res[3]) const {
+  const Eigen::Vector3d r = local_inverse_coordinates_of(Eigen::Vector3d(src[0],src[1],src[2]));
+  for (int i = 0; i < 3; ++i){
+    res[i] = r[i];}
+}
+
+void Frame::get_coordinates_of_in(const double src[3], double res[3], const Frame* const in) const {
+  const Eigen::Vector3d r = coordinates_of_in(Eigen::Vector3d(src[0],src[1],src[2]), in);
+  for (int i = 0; i < 3; ++i){
+    res[i] = r[i];}
+}
+
+void Frame::get_coordinates_of_from(const double src[3], double res[3], const Frame* const from) const {
+  const Eigen::Vector3d r = coordinates_of_from(Eigen::Vector3d(src[0],src[1],src[2]), from);
+  for (int i = 0; i < 3; ++i){
+    res[i] = r[i];}
+}
