+void Frame::get_local_transform_of(const double src[3], double res[3]) const {
+  Eigen::Vector3d r = local_transform_of(Eigen::Vector3d(src[0],src[1],src[2]));
+  for (int i = 0; i < 3; ++i){
+    res[i] = r[i];}
+}
