+void Frame::get_transform_of_in(const double src[3], double res[3], const Frame* const in) const {
+  Eigen::Vector3d r = transform_of_in(Eigen::Vector3d(src[0],src[1],src[2]), in);
+  for (int i = 0; i < 3; ++i){
+    res[i] = r[i];}
+}
