+void Frame::get_transform_of_from(const double src[3], double res[3], const Frame* const from) const {
+  Eigen::Vector3d r = transform_of_from(Eigen::Vector3d(src[0],src[1],src[2]), from);
+  for (int i = 0; i < 3; ++i){
+    res[i] = r[i];}
+}
+
+void Frame::align_with_frame(const Frame* const frame, bool move, double threshold) {
+  Eigen::Vector3d directions[2][3];
+  for (int d = 0; d < 3; ++d) {
+      Eigen::Vector3d dir((d==0)? 1.0 : 0.0, (d==1)? 1.0 : 0.0, (d==2)? 1.0 : 0.0);
+      if (frame){
+	        directions[0][d] = frame->inverse_transform_of(dir);}
+      else{
+	        directions[0][d] = dir;}
+      directions[1][d] = inverse_transform_of(dir);
+  }
+
+  double maxProj = 0.0f;
+  double proj = 0.0;
+  unsigned short index[2];
+  index[0] = index[1] = 0;
+  for (int i=0; i<3; ++i){
+    for (int j=0; j<3; ++j){
+		if ((proj=fabs(directions[0][i].dot(directions[1][j]))) >= maxProj) {
+    	  index[0] = i;
+    	  index[1] = j;
+    	  maxProj  = proj;
+          }
+     }
+  }
+
+  Frame old;
+  old=*this;
+
+  double coef = directions[0][index[0]].dot(directions[1][index[1]]);
+  if (fabs(coef) >= threshold) {
+		  const Eigen::Vector3d axis =  directions[0][index[0]].cross(directions[1][index[1]]);
+      double angle = asin(axis.norm());
+      if (coef >= 0.0)
+	       angle = -angle;
+      // set_orientation(Eigen::Quaterniond(axis, angle) * orientation());
+      //axis.normalize();
+      Eigen::AngleAxisd angleAxis(angle, axis);
+      rotate(rotation().inverse() * Eigen::Quaterniond(angleAxis) * orientation());
+
+      // Try to align an other axis direction
+      unsigned short d = (index[1]+1) % 3;
+      Eigen::Vector3d dir((d==0)? 1.0 : 0.0, (d==1)? 1.0 : 0.0, (d==2)? 1.0 : 0.0);
+      dir = inverse_transform_of(dir);
+
+      double max = 0.0f;
+      for (int i=0; i<3; ++i) {
+    		double proj = fabs(directions[0][i].dot(dir));
+    	  if (proj > max) {
+    	      index[0] = i;
+    	      max = proj;
+    	  }
+    	}
+
+      if (max >= threshold) {
+    		const Eigen::Vector3d axis = directions[0][index[0]].cross(dir);
+    	  double angle = asin(axis.norm());
+    	  if (directions[0][index[0]].dot(dir) >= 0.0)
+    	    angle = -angle;
+    	  // set_orientation(Eigen::Quaterniond(axis, angle) * orientation());
+        //axis.normalize();
+        Eigen::AngleAxisd angleAxis(angle, axis);
+        rotate(rotation().inverse() * Eigen::Quaterniond(angleAxis) * orientation());
+    	}
+    }
+
+  if (move) {
+      Eigen::Vector3d center;
+      if (frame)
+	     center = frame->position();
+
+      // set_position(center - orientation().rotate(old.coordinates_of(center)));
+      translate(center - orientation()._transformVector(old.coordinates_of(center)) - translation());
+    }
+}
+
+void Frame::project_on_line(const Eigen::Vector3d& origin, const Eigen::Vector3d& direction) {
+  const Eigen::Vector3d shift = origin - position();
+  Eigen::Vector3d proj = shift;
+
+  if (direction.squaredNorm() < 1.0E-10)
+	  std::cout << "Vec::projectOnAxis: axis direction is not normalized (norm)."<<std::endl;;
+
+  proj = (proj.dot(direction) /direction.squaredNorm()) * direction;
+  translate(shift-proj);
+}
+
