+void GLFWViewer::render(){
+ 	glClear( GL_COLOR_BUFFER_BIT);
+    pre_draw();
+
+	/*if (FLAGS_enable_hdmap_input) show_map(_frame_content, FLAGS_show_map_roi, FLAGS_show_map_boundary); */
