+    return _rows_covered[row];
+  }
+
+  // Cover row 'row'.
+  void cover_row(int row) {
+    _rows_covered[row] = true;
+  }
+
+  // Uncover row 'row'.
+  void uncover_row(int row) {
+    _rows_covered[row] = false;
+  }
+
+  // Is column col covered?
