+double ComputeMean(const std::vector<double>& nums, size_t start, size_t end) {
+  int count = 0;
+  double sum = 0.0;
+  for (size_t i = start; i <= end && i < nums.size(); i++) {
+    sum += nums[i];
+    ++count;
+  }
+  return (count == 0) ? 0.0 : sum / count;
+}
