+bool DpStGraph::CheckIsFollowByT(const StGraphBoundary& boundary) const {
+  return boundary.min_t() < FLAGS_st_follow_max_start_t &&
+         boundary.max_t() > FLAGS_st_follow_min_end_t;
+}
