-    int prefix_len = prefix.size();
-    for (; it != it_end; ++it) {
-      if (it->path().leaf().string().compare(0, prefix_len, prefix, 0,
-                                             prefix_len) == 0) {
-        std::cout << "remove tmp msg file: " << it->path().leaf().string()
-                  << std::endl;
-        boost::filesystem::remove(it->path());
-      }
-    }
-  }
-}
