-static void setFromRotatedBasis(Eigen::Quaterniond& q, const Eigen::Vector3d& X, const Eigen::Vector3d& Y, const Eigen::Vector3d& Z)
-{
-    Eigen::Matrix3d m;
-    double normX = X.norm();
-    double normY = Y.norm();
-    double normZ = Z.norm();
-    for (int i = 0; i < 3; ++i)
-    {
-    m(i, 0) = X[i] / normX;
-    m(i, 1) = Y[i] / normY;
-    m(i, 2) = Z[i] / normZ;
-    }
-    q = Eigen::Quaterniond(m);
-}
