+void GLFWViewer::GetClassColor(int cls, float rgb[3]) {
+  switch (cls) {
+  case 0:
+    rgb[0] = 0.5;
+    rgb[1] = 0;
+    rgb[2] = 1; //紫
+    break;
+  case 1:
+    rgb[0] = 0;
+    rgb[1] = 1;
+    rgb[2] = 1; //青
+    break;
+  case 2:
+    rgb[0] = 1;
+    rgb[1] = 1;
+    rgb[2] = 0; //黄
+    break;
+  case 3:
+    rgb[0] = 1;
+    rgb[1] = 0.5;
+    rgb[2] = 0.5; //赤
+    break;
+  case 4:
+    rgb[0] = 0;
+    rgb[1] = 0;
+    rgb[2] = 1; //蓝
+    break;
+  case 5:
+    rgb[0] = 0;
+    rgb[1] = 1;
+    rgb[2] = 0; //绿
+    break;
+  case 6:
+    rgb[0] = 1;
+    rgb[1] = 0.5;
+    rgb[2] = 0; //橙
+    break;
+  case 7:
+    rgb[0] = 1;
+    rgb[1] = 0;
+    rgb[2] = 0; //赤
+    break;
+  }
 }
 
