+bool PncMap::CreatePathFromRouting(
+    const ::apollo::routing::RoutingResponse &routing, Path *const path) const {
+  LaneSegments segments;
+  for (const auto &way : routing.route()) {
+    if (way.has_road_info() && !way.road_info().passage_region().empty()) {
+      for (const auto &segment : way.road_info().passage_region(0).segment()) {
+        auto lane_ptr = hdmap_.get_lane_by_id(hdmap::MakeMapId(segment.id()));
+        if (!lane_ptr) {
+          AERROR << "Failed to fine lane: " << segment.id();
+          return false;
+        }
+        segments.emplace_back(lane_ptr, segment.start_s(), segment.end_s());
+      }
+    } else if (way.has_junction_info()) {
+      for (const auto &segment :
+           way.junction_info().passage_region().segment()) {
+        auto lane_ptr = hdmap_.get_lane_by_id(hdmap::MakeMapId(segment.id()));
+        if (!lane_ptr) {
+          AERROR << "Failed to fine lane: " << segment.id();
+          return false;
+        }
+        segments.emplace_back(lane_ptr, segment.start_s(), segment.end_s());
+      }
+    }
+  }
+  CreatePathFromLaneSegments(segments, path);
+  return true;
+}
+
+void PncMap::CreatePathFromLaneSegments(const LaneSegments &segments,
+                                        Path *const path) {
+  std::vector<hdmap::MapPathPoint> points;
+  for (const auto &segment : segments) {
+    append_lane_to_points(segment.lane, segment.start_s, segment.end_s,
+                          &points);
+  }
+  *path = hdmap::Path(points, segments, kTrajectoryApproximationMaxError);
+}
