+  const auto& adc_boundary = reference_line_info->ADCBoundary();
+  for (const auto* path_obstacle : path_decision->path_obstacles().Items()) {
+    if (path_obstacle->perception_sl_boundary().end_s() >=
+        adc_boundary.end_s()) {
+      continue;
