+        reference_line_info->IsOnRightLane(bounding_box.center())) {
+      ObjectDecisionType ignore;
+      ignore.mutable_ignore();
+      path_decision->AddLateralDecision(name(), path_obstacle->Id(), ignore);
+    }
+  }
   return true;
 }

