+  junction_id.set_id("1183");
+  JunctionInfoConstPtr junction_ptr = hdmap_impl_.GetJunctionById(
+                                                            junction_id);
+  EXPECT_TRUE(nullptr != junction_ptr);
+  EXPECT_STREQ(junction_id.id().c_str(), junction_ptr->id().id().c_str());
+}
