+  point.set_y(4140727.02);
+  point.set_z(0.0);
+  EXPECT_EQ(0, hdmap_impl_.GetNearestLane(point, &lane, &s, &l));
+  EXPECT_EQ("773_1_-2", lane->id().id());
+  EXPECT_NEAR(s, 25.891, 1e-3);
+  EXPECT_NEAR(l, -3.257, 1e-3);
+}
