+  point.set_x(586434.75);
+  point.set_y(4140746.94);
+  point.set_z(0.0);
+  EXPECT_EQ(0, hdmap_impl_.GetRoadBoundaries(point, 4.5,
+                                        &road_boundaries,
+                                        &junctions));
+  EXPECT_EQ(1, road_boundaries.size());
+  EXPECT_EQ(1, junctions.size());
+}
